<script>
  import { toSentence } from '@splendidlabz/utils'
  import { randomString } from '@splendidlabz/utils/dom'
  import { init } from '../../utils'
  import SVG from '../Icon/Icon.svelte'
  import TextInput from './TextInput.svelte'

  let {
    label: labelProp = null,
    group = $bindable(null),
    ref = $bindable(null),
    checked = $bindable(false),
    class: klass = '',
    icon = null,
    iconClass = null,
    fieldClass = '',
    labelClass = '',
    id = randomString(8),
    name,
    value = null,
    readonly = null,
    disabled = null,
    hasInput = false,
    onchange = null,
    ...rest
  } = $props()

  let label = $state(null)

  init(() => {
    label = labelProp
    if (!name) throw new Error('Radio requires a name')
    if (!value) throw new Error('Radio requires a value')
    // Create label if not provided
    if (!label && label !== '') label = toSentence(value)
  })

  // Sends the checked value upwards
  function handleChange(event) {
    checked = ref.checked
    if (onchange) onchange(event)
  }
</script>

<div class="radio {klass}" class:checked class:disabled class:readonly>
  <div class="group">
    <div class="radiomark-container">
      <input
        {...rest}
        bind:this={ref}
        {id}
        {name}
        class="input {fieldClass}"
        {checked}
        disabled={disabled || readonly}
        onchange={handleChange}
        type="radio"
        {value}
        bind:group
      />

      {#if readonly && checked}
        <input {name} {checked} type="hidden" {value} />
      {/if}

      {#if icon}
        <SVG class="radiomark {iconClass}" {icon} />
      {:else}
        <svg class="radiomark" viewBox="0 0 24 24">
          <circle cx="12" cy="12" r="5" />
        </svg>
      {/if}
    </div>

    {#if label}
      <label class="label {labelClass}" for={id}> {label} </label>
    {/if}
  </div>

  {#if hasInput}
    <TextInput name="{name}-input" />
  {/if}
</div>
